import path from 'path'
import fs from 'fs'
import glob from 'glob'

/**
 * Script for automatically generating a file which has a series of `require` statements for
 * importing JSON contract artifacts. We do this to preserve browser compatibility.
 */
const main = async () => {
    const contractArtifactsFolder = path.resolve(
        __dirname,
        `../src/abi`
    )

    const artifactPaths = glob
        .sync(`${contractArtifactsFolder}/**.json`, { ignore: `${contractArtifactsFolder}/**test.json` })
        .filter((match) => {
            // Filter out the debug outputs.
            return !match.endsWith('.dbg.json')
        })

    const content = `
    /* eslint-disable @typescript-eslint/no-var-requires, no-empty */
    /*
    THIS FILE IS AUTOMATICALLY GENERATED.
    DO NOT EDIT.
    */

    ${artifactPaths
            .map((artifactPath) => {
                // eslint-disable-next-line @typescript-eslint/no-var-requires
                const artifact = require(artifactPath)
                const contractName = artifactPath.match(/([_a-zA-Z0-9]*?)\.json$/)[1]
                // console.log('artifact', artifact);
                // handles the case - '\u' (\utils folder) is considered as an unicode encoded char
                const pattern = /\\/g
                const relPath = path
                    .relative(__dirname, artifactPath)
                    .replace(pattern, '/')
                return `
        let ${contractName}
        try {
          ${contractName} = require('${relPath}')
        } catch {}
        `
            })
            .join('\n')}

    export const getContractArtifact = (name: string): any => {
      return {
        ${artifactPaths
            .map((artifactPath) => {
                // eslint-disable-next-line @typescript-eslint/no-var-requires
                const artifact = require(artifactPath)
                const contractName = artifactPath.match(/([_a-zA-Z0-9]*?)\.json$/)[1]
                return `${contractName}`
            })
            .join(',\n')}
      }[name]
    }
    `

    fs.writeFileSync(
        path.resolve(contractArtifactsFolder, `../contract-artifacts.ts`),
        content
    )
}

main()
